// Build parallel fetch tasks from sources config
const input = $input.first().json;
const sources = input.sources || {};
const prefs = input.preferences || {};
const tasks = [];

if (sources.adzuna?.enabled) {
  for (const q of sources.adzuna.searchQueries || []) {
    tasks.push({ type: 'adzuna', query: q });
  }
}
if (sources.greenhouse?.enabled) {
  for (const board of sources.greenhouse.boards || []) {
    tasks.push({ type: 'greenhouse', board });
  }
}
if (sources.lever?.enabled) {
  for (const company of sources.lever.companies || []) {
    tasks.push({ type: 'lever', company });
  }
}
if (sources.ashby?.enabled) {
  for (const board of sources.ashby.jobBoards || []) {
    tasks.push({ type: 'ashby', board });
  }
}
if (sources.rss?.enabled) {
  for (const feed of sources.rss.feeds || []) {
    if (feed.enabled !== false) tasks.push({ type: 'rss', feed });
  }
}

return tasks.map((t) => ({ json: { ...t, preferences: prefs } }));

const SAUDI = ['riyadh','jeddah','dammam','khobar','dhahran','makkah','madinah','neom','tabuk','saudi','ksa'];
const REMOTE = ['remote','work from home','wfh','anywhere'];

function slugify(t){return String(t||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
function stripHtml(h){return String(h||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}
function workType(loc,desc){const t=`${loc} ${desc}`.toLowerCase();if(REMOTE.some(k=>t.includes(k)))return'remote';if(t.includes('hybrid'))return'hybrid';if(t.includes('on-site')||t.includes('onsite'))return'onsite';return'unknown';}
function norm(raw,source){
  const title=raw.title||raw.text||'Unknown';
  const company=raw.company||raw.company_name||source;
  const location=raw.location||raw.location_name||'Unknown';
  const description=stripHtml(raw.description||raw.content||'');
  const applyUrl=raw.applyUrl||raw.url||raw.absolute_url||raw.link||'';
  const loc=String(location).toLowerCase();
  const id=slugify([company,title,location,applyUrl].join('|')).slice(0,120);
  return {id,title:String(title).trim(),company:String(company).trim(),location:String(location).trim(),salary:raw.salary||null,description,applyUrl:String(applyUrl).trim(),source,datePosted:raw.datePosted?new Date(raw.datePosted).toISOString():null,workType:workType(location,description),isSaudi:SAUDI.some(c=>loc.includes(c)),isRemote:REMOTE.some(c=>loc.includes(c)),fetchedAt:new Date().toISOString()};
}

const item = $input.first().json;
const jobs = [];

try {
  if (item.type === 'adzuna') {
    const appId = $env.ADZUNA_APP_ID;
    const appKey = $env.ADZUNA_APP_KEY;
    if (!appId || !appKey) return [{ json: { _skip: true, reason: 'Adzuna credentials missing' } }];
    const url = `https://api.adzuna.com/v1/api/jobs/sa/search/1?app_id=${appId}&app_key=${appKey}&what=${encodeURIComponent(item.query)}&results_per_page=50`;
    const data = await this.helpers.httpRequest({ method: 'GET', url, json: true });
    for (const r of data.results || []) {
      jobs.push(norm({title:r.title,company:r.company?.display_name,location:r.location?.display_name,description:r.description,applyUrl:r.redirect_url,datePosted:r.created,salary:r.salary_min&&r.salary_max?`${r.salary_min}-${r.salary_max}`:null},'adzuna'));
    }
  }
  else if (item.type === 'greenhouse') {
    const url = `https://boards-api.greenhouse.io/v1/boards/${item.board}/jobs?content=true`;
    const data = await this.helpers.httpRequest({ method: 'GET', url, json: true });
    for (const r of data.jobs || []) {
      jobs.push(norm({title:r.title,company:item.board,location:r.location?.name,description:r.content,applyUrl:r.absolute_url,datePosted:r.updated_at},'greenhouse'));
    }
  }
  else if (item.type === 'lever') {
    const url = `https://api.lever.co/v0/postings/${item.company}?mode=json`;
    const data = await this.helpers.httpRequest({ method: 'GET', url, json: true });
    for (const r of data || []) {
      jobs.push(norm({title:r.text,company:item.company,location:r.categories?.location,description:r.descriptionPlain||r.description,applyUrl:r.hostedUrl,datePosted:r.createdAt},'lever'));
    }
  }
  else if (item.type === 'ashby') {
    const url = `https://api.ashbyhq.com/posting-api/job-board/${item.board}`;
    const data = await this.helpers.httpRequest({ method: 'GET', url, json: true });
    for (const r of data.jobs || []) {
      jobs.push(norm({title:r.title,company:item.board,location:r.location,description:r.descriptionHtml,applyUrl:r.jobUrl,datePosted:r.publishedAt},'ashby'));
    }
  }
  else if (item.type === 'rss') {
    const xml = await this.helpers.httpRequest({ method: 'GET', url: item.feed.url });
    const items = [...String(xml).matchAll(/<item>([\s\S]*?)<\/item>/gi)];
    for (const m of items) {
      const block = m[1];
      const get = (tag) => (block.match(new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i')) || [])[1] || (block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i')) || [])[1] || '';
      jobs.push(norm({title:get('title'),company:item.feed.name,location:'Remote',description:get('description'),applyUrl:get('link'),datePosted:get('pubDate')},`rss:${item.feed.name}`));
    }
  }
} catch (e) {
  return [{ json: { _error: true, source: item.type, message: e.message } }];
}

if (jobs.length === 0) return [{ json: { _empty: true, source: item.type } }];
return jobs.map((j) => ({ json: j }));
